result=js(r'''(async()=>{
const T=await import('three'),r=await import('./js/world/city-rollout.js'),{stops}=await import('./js/content.js'),{routePoints,routeCurve}=await import('./js/world/layout.js'),{buildCity}=await import('./js/world/city.js'),{createTowerSlice}=await import('./js/world/tower-slice.js');const check=(v,m)=>{if(!v)throw Error(m)},pts=routePoints(stops.length),plots=[];buildCity(()=>{},stops,pts,routeCurve(T,pts),undefined,undefined,p=>plots.push(p));
check(typeof r.rolloutRecipe==='function'&&typeof r.classifyCompletion==='function','deterministic variety/completion API');
const towers=plots.filter(p=>r.classifyPlot(p)==='tower'),families=new Set,profiles=new Set;
for(const p of towers){const recipe=r.rolloutRecipe(p,'tower',plots),g=createTowerSlice(p,recipe);families.add(recipe.silhouette);const positions=g.children[0].geometry.attributes.position,points=[];for(let i=0;i<positions.count;i++)if(positions.getY(i)>p.height*.8)points.push([positions.getX(i)/p.width,positions.getZ(i)/p.depth]);const xs=points.map(v=>v[0]*p.width/(p.width-.4)),lo=Math.min(...xs),hi=Math.max(...xs);profiles.add(JSON.stringify([Math.round((hi-lo)*100),Math.round((hi+lo)*50)]));const b=new T.Box3().setFromObject(g);check(b.min.x>=p.x-p.width/2-.001&&b.max.x<=p.x+p.width/2+.001&&b.min.z>=p.z-p.depth/2-.001&&b.max.z<=p.z+p.depth/2+.001&&b.max.y<=p.height+.001,'tower envelope');check(JSON.stringify(recipe)===JSON.stringify(r.rolloutRecipe(p,'tower',plots.slice().reverse())),'stable skyline selection');g.children.forEach(m=>m.geometry.dispose());}
check(families.size===3&&profiles.size>=3,'three actual tower silhouette families');
check(r.classifyCompletion({id:'rear-test',kind:'midrise',width:10,depth:8,height:6,z:-108})==='C','cheap coherent rear mass');check(r.classifyCompletion({id:'block-test',kind:'midrise',width:10,depth:10,height:9,z:-34})==='A','safe compact residential');check(r.classifyCompletion({id:'glasgow-tenement-test',kind:'midrise',width:10,depth:10,height:6,z:0})==='B','special identity preserved');
const compact=plots.filter(p=>r.classifyCompletion(p)==='A'||r.classifyCompletion(p)==='C');check(compact.length>=81,'compact existing lots classified');const g=r.createCityRollout(compact,plots);check(g.children.every(c=>c.children.length===3),'three buckets per cell');for(const c of g.children)for(const lod of c.userData.lods)for(const geometry of lod){const a=geometry.attributes.position,own=compact.filter(p=>c.userData.plotIds.includes(p.id));for(let i=0;i<a.count;i++){const x=a.getX(i)+c.position.x,y=a.getY(i),z=a.getZ(i)+c.position.z;check(Number.isFinite(x+y+z)&&own.some(p=>Math.abs(x-p.x)<=p.width/2+.001&&Math.abs(z-p.z)<=p.depth/2+.001&&y>=-.001&&y<=p.height+.001),'compact footprint/height');}}g.userData.dispose();return {pass:true,towerFamilies:[...families],completion:compact.reduce((n,p)=>(n[r.classifyCompletion(p)]++,n),{A:0,C:0})};})()''')
print(result)
assert isinstance(result,dict) and result.get('pass'),result
